{
  "interpretation": {
    "name": "Line2NutrunnerTightening",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Bring the shared nutrunner NR7 to station st2, tighten the F30 fasteners, return the tool to the crib and release it so line 3 can use it.",
    "constraints": [
      "NR7 is reserved exclusively for line 2 and released after it is back in the crib",
      "NR7 is at st2 (transport-tool to 'station' completed) before configure-tool and tighten-fasteners",
      "The tightening program comes only from get-program, with no numeric process values in the Recipe",
      "The tightening is evaluated against its program and recorded for traceability",
      "Only agvexecutor consumes transport-tool",
      "Every tool-using Step renews the lease with the reservation token, and each single Step is shorter than the 120 s lease"
    ],
    "preference": "Minimise the time NR7 is away from the crib: reserve and fetch the program before the tool leaves, and run evaluation and recording in parallel with the return transport and release.",
    "priority": "high",
    "horizon": "Single execution for the current request; the tool becomes available to line 3 right after release.",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-nutrunner-tightening",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {
            "name": "reserve-nr7",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "fetch-program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "return-and-close",
        "steps": [
          {
            "name": "configure-nr7",
            "service": "configure-tool",
            "next": ["tighten-st2"],
            "dep": ["reserve-nr7", "fetch-program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-st2",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["reserve-nr7", "configure-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-and-close",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release-nr7"],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-nr7",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": null,
            "params": {}
          },
          {
            "name": "evaluate-st2",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-st2", "fetch-program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-st2",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-st2"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
